// Before: async all the way
[HttpGet]
public async Task<ActionResult<List<Order>>> GetOrders()
{
    return await _dbContext.Orders.ToListAsync();
}

// After deployment: synchronous block introduced
[HttpGet]
public ActionResult<List<Order>> GetOrders()
{
    return _dbContext.Orders.ToListAsync().Result; // Blocks thread!
}
